//! The `OpenAPI` gate (T-98 items 1 and 2): the document is generated by the `work-http` `openapi` example, committed at `sdks/openapi/work-v1.json` and compared byte for byte; every operation names exactly one catalog action in `x-work-action` (E-45 item 3), a changing operation takes `Idempotency-Key` (P-54 item 4), a changing operation on an existing item takes `If-Match` (P-54 item 5), every error response is `application/problem+json` and every response carries `Request-Id` and `RateLimit` (P-54 item 9).

use std::collections::BTreeSet;
use std::path::Path;
use std::process::Command;

use serde_json::Value;

use crate::Violation;
use crate::contracts::source::{ACTIONS_RS, actions};
use crate::contracts::{violation, write};

pub(crate) const DOCUMENT: &str = "sdks/openapi/work-v1.json";

const RULE: &str = "openapi";

const METHODS: [&str; 8] = [
    "get", "put", "post", "delete", "options", "head", "patch", "trace",
];

const CHANGING: [&str; 4] = ["put", "post", "delete", "patch"];

const PROBLEM_JSON: &str = "application/problem+json";

const RESPONSE_HEADERS: [&str; 2] = ["Request-Id", "RateLimit"];

/// The document the code generates.
pub(crate) fn generate(root: &Path) -> Result<String, String> {
    let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_owned());
    let output = Command::new(&cargo)
        .args([
            "run",
            "--locked",
            "--quiet",
            "--package",
            "work-http",
            "--example",
            "openapi",
        ])
        .current_dir(root)
        .output()
        .map_err(|e| format!("{cargo} run: {e}"))?;
    if !output.status.success() {
        return Err(format!(
            "the openapi example failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    String::from_utf8(output.stdout).map_err(|e| format!("the openapi example: {e}"))
}

/// `cargo xtask openapi`.
pub(crate) fn write_document(root: &Path) -> Result<(), String> {
    write(root, DOCUMENT, &generate(root)?)
}

/// `cargo xtask check openapi`.
pub(crate) fn check(root: &Path) -> Result<Vec<Violation>, String> {
    let generated = generate(root)?;
    let committed = std::fs::read_to_string(root.join(DOCUMENT)).unwrap_or_default();
    let mut out = Vec::new();
    if committed != generated {
        out.push(violation(
            RULE,
            DOCUMENT,
            "differs from the document the code generates; run `cargo xtask openapi` (T-98 item 2)"
                .to_owned(),
        ));
    }
    let doc: Value =
        serde_json::from_str(&generated).map_err(|e| format!("generated {DOCUMENT}: {e}"))?;
    let catalog = actions(
        &std::fs::read_to_string(root.join(ACTIONS_RS))
            .map_err(|e| format!("{ACTIONS_RS}: {e}"))?,
    );
    if catalog.is_empty() {
        return Err(format!("{ACTIONS_RS} names no action"));
    }
    out.extend(
        lint(&doc, &catalog)
            .into_iter()
            .map(|m| violation(RULE, DOCUMENT, m)),
    );
    Ok(out)
}

/// The object a local `$ref` points at, or `value` itself.
fn resolve<'a>(doc: &'a Value, value: &'a Value) -> &'a Value {
    let Some(pointer) = value
        .get("$ref")
        .and_then(Value::as_str)
        .and_then(|r| r.strip_prefix('#'))
    else {
        return value;
    };
    doc.pointer(pointer).unwrap_or(value)
}

fn header_parameters<'a>(doc: &'a Value, lists: [Option<&'a Value>; 2]) -> BTreeSet<String> {
    lists
        .into_iter()
        .flatten()
        .filter_map(Value::as_array)
        .flatten()
        .map(|p| resolve(doc, p))
        .filter(|p| p.get("in").and_then(Value::as_str) == Some("header"))
        .filter_map(|p| p.get("name").and_then(Value::as_str))
        .map(str::to_ascii_lowercase)
        .collect()
}

/// Lint findings of an `OpenAPI` document against the action catalog.
pub(crate) fn lint(doc: &Value, catalog: &BTreeSet<String>) -> Vec<String> {
    let mut out = Vec::new();
    let Some(paths) = doc.get("paths").and_then(Value::as_object) else {
        return out;
    };
    for (path, item) in paths {
        let item = resolve(doc, item);
        for method in METHODS {
            let Some(operation) = item.get(method) else {
                continue;
            };
            let at = format!("{} {path}", method.to_uppercase());
            match operation.get("x-work-action") {
                Some(Value::String(action)) if catalog.contains(action) => {}
                Some(Value::String(action)) => out.push(format!(
                    "{at}: x-work-action `{action}` is not an action of the catalog (E-45 item 3)"
                )),
                Some(_) => out.push(format!(
                    "{at}: x-work-action must name exactly one action (E-45 item 3)"
                )),
                None => out.push(format!("{at}: names no x-work-action (E-45 item 3)")),
            }
            let headers =
                header_parameters(doc, [item.get("parameters"), operation.get("parameters")]);
            if CHANGING.contains(&method) {
                if !headers.contains("idempotency-key") {
                    out.push(format!(
                        "{at}: a changing operation takes Idempotency-Key (P-54 item 4)"
                    ));
                }
                if path.contains('{') && !headers.contains("if-match") {
                    out.push(format!(
                        "{at}: a changing operation on an existing item takes If-Match (P-54 item 5)"
                    ));
                }
            }
            let responses = operation
                .get("responses")
                .and_then(Value::as_object)
                .into_iter()
                .flatten();
            for (status, response) in responses {
                let response = resolve(doc, response);
                let error =
                    status.starts_with('4') || status.starts_with('5') || status == "default";
                if error
                    && response
                        .pointer(&format!("/content/{}", PROBLEM_JSON.replace('/', "~1")))
                        .is_none()
                {
                    out.push(format!(
                        "{at}: response {status} is not {PROBLEM_JSON} (T-98 item 6)"
                    ));
                }
                let names: BTreeSet<String> = response
                    .get("headers")
                    .and_then(Value::as_object)
                    .into_iter()
                    .flatten()
                    .map(|(name, _)| name.to_ascii_lowercase())
                    .collect();
                for header in RESPONSE_HEADERS {
                    if !names.contains(&header.to_ascii_lowercase()) {
                        out.push(format!(
                            "{at}: response {status} does not declare {header} (P-54 item 9)"
                        ));
                    }
                }
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    fn catalog() -> BTreeSet<String> {
        ["work:read", "work:commit"]
            .into_iter()
            .map(str::to_owned)
            .collect()
    }

    fn response(content: &str) -> Value {
        json!({
            "description": "x",
            "headers": {"Request-Id": {"schema": {}}, "RateLimit": {"schema": {}}},
            "content": {content: {"schema": {}}}
        })
    }

    fn header(name: &str) -> Value {
        json!({"in": "header", "name": name, "required": true, "schema": {"type": "string"}})
    }

    fn good() -> Value {
        json!({
            "openapi": "3.1.0",
            "paths": {
                "/v1/works/{work}": {
                    "parameters": [{"in": "path", "name": "work", "required": true}],
                    "get": {
                        "x-work-action": "work:read",
                        "responses": {"200": response("application/json"), "404": response(PROBLEM_JSON)}
                    },
                    "post": {
                        "x-work-action": "work:commit",
                        "parameters": [header("Idempotency-Key"), {"$ref": "#/components/parameters/IfMatch"}],
                        "responses": {"201": response("application/json"), "default": {"$ref": "#/components/responses/Problem"}}
                    }
                }
            },
            "components": {
                "parameters": {"IfMatch": header("If-Match")},
                "responses": {"Problem": response(PROBLEM_JSON)}
            }
        })
    }

    // E-45 T-98
    #[test]
    fn e_45_every_mutating_operation_names_one_action() {
        assert!(
            lint(&good(), &catalog()).is_empty(),
            "{:?}",
            lint(&good(), &catalog())
        );
        let mut doc = good();
        doc["paths"]["/v1/works/{work}"]["post"]
            .as_object_mut()
            .unwrap()
            .remove("x-work-action");
        let found = lint(&doc, &catalog());
        assert_eq!(
            found,
            ["POST /v1/works/{work}: names no x-work-action (E-45 item 3)"]
        );
        doc["paths"]["/v1/works/{work}"]["post"]["x-work-action"] =
            json!(["work:read", "work:commit"]);
        assert!(lint(&doc, &catalog())[0].contains("exactly one action"));
        doc["paths"]["/v1/works/{work}"]["post"]["x-work-action"] = json!("work:gate_decision");
        assert!(lint(&doc, &catalog())[0].contains("not an action of the catalog"));
    }

    // T-98
    #[test]
    fn t_98_changing_operations_take_idempotency_key_and_if_match() {
        let mut doc = good();
        doc["paths"]["/v1/works/{work}"]["post"]["parameters"] = json!([]);
        let found = lint(&doc, &catalog());
        assert_eq!(found.len(), 2, "{found:?}");
        assert!(found[0].contains("Idempotency-Key"));
        assert!(found[1].contains("If-Match"));
        let mut collection = good();
        let post = collection["paths"]["/v1/works/{work}"]["post"].clone();
        collection["paths"] = json!({"/v1/works": {"post": post}});
        collection["paths"]["/v1/works"]["post"]["parameters"] = json!([header("idempotency-key")]);
        assert!(lint(&collection, &catalog()).is_empty());
    }

    // T-98
    #[test]
    fn t_98_errors_are_problem_json_and_responses_carry_request_id_and_ratelimit() {
        let mut doc = good();
        doc["paths"]["/v1/works/{work}"]["get"]["responses"]["404"] = response("application/json");
        let found = lint(&doc, &catalog());
        assert_eq!(found.len(), 1, "{found:?}");
        assert!(found[0].contains("is not application/problem+json"));
        doc["paths"]["/v1/works/{work}"]["get"]["responses"]["404"] = response(PROBLEM_JSON);
        doc["paths"]["/v1/works/{work}"]["get"]["responses"]["200"]["headers"] =
            json!({"Request-Id": {}});
        let found = lint(&doc, &catalog());
        assert_eq!(
            found,
            ["GET /v1/works/{work}: response 200 does not declare RateLimit (P-54 item 9)"]
        );
        assert!(lint(&json!({"openapi": "3.1.0"}), &catalog()).is_empty());
    }
}
